const { spawn } = require('child_process')

module.exports = gnome_dconf

// reads and writes raw dconf keys, values are GVariant text like "'Adwaita'" or "uint32 1"
// env picks the dbus session and dconf database (tests use a sandbox)
function gnome_dconf ({ env = process.env } = {}) {
  const api = { dump, read_dir, read, write, reset, watch }
  return api

  function dump (dir) { return run({ args: ['dump', dir], env }) }
  async function read_dir (dir) { return parse_dump(dir, await dump(dir)) }
  async function read (key) { return (await run({ args: ['read', key], env })).trim() || null }
  function write (key, value) { return run({ args: ['write', key, value], env }) }
  function reset (key) { return run({ args: key.endsWith('/') ? ['reset', '-f', key] : ['reset', key], env }) }

  // on_change({ key, value }), value is null when the key was reset, key ends with / when a whole dir changed
  function watch (dir, on_change) {
    const child = spawn('dconf', ['watch', dir], { stdio: ['ignore', 'pipe', 'inherit'], env })
    const state = { rest: '' }
    child.stdout.setEncoding('utf8')
    child.stdout.on('data', text => read_watch_output({ text, state, on_change }))
    return { stop: () => child.kill() }
  }
}

/***************************************
PARSE DUMP
`dconf dump` prints sections like [sub/dir] and lines like key=value, values are single line GVariant text
***************************************/
function parse_dump (dir, text) {
  const settings = {}
  let section = dir
  for (const line of text.split('\n')) {
    const eq = line.indexOf('=')
    if (line.startsWith('[')) section = line === '[/]' ? dir : dir + line.slice(1, -1) + '/'
    else if (eq > 0) settings[section + line.slice(0, eq)] = line.slice(eq + 1)
  }
  return settings
}

/***************************************
READ WATCH OUTPUT
`dconf watch` prints "/full/key\n  value\n\n", value is the word unset after a reset
***************************************/
function read_watch_output ({ text, state, on_change }) {
  const blocks = (state.rest + text).split('\n\n')
  state.rest = blocks.pop()
  for (const block of blocks) {
    const [key, value = ''] = block.split('\n')
    const trimmed = value.trim()
    on_change({ key, value: trimmed === 'unset' ? null : trimmed })
  }
}

/***************************************
RUN
***************************************/
function run ({ args, env }) {
  return new Promise(start_process)
  function start_process (resolve, reject) {
    const child = spawn('dconf', args, { stdio: ['ignore', 'pipe', 'pipe'], env })
    const out = []
    const err = []
    child.stdout.on('data', data => out.push(data))
    child.stderr.on('data', data => err.push(data))
    child.on('error', reject)
    child.on('close', code => code === 0 ? resolve(Buffer.concat(out).toString()) : reject(new Error(`dconf ${args.join(' ')}: ${Buffer.concat(err).toString().trim()}`)))
  }
}
